head.script:
// 화면 리사이징

scwin.gAcptNo;
scwin.gMainFormCd;
scwin.gFormVer;
scwin.gIsurCd;
scwin.gDate;
scwin.gProcDepCd;
scwin.gDepCd = js_dep_cd;
scwin.gEmpNo = js_emp_no;
scwin.gLdMktTp = js_market;

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    await scwin.gform_onload();
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

/**
 * @method
 * @name showOptButton
 * @description 조건에 따른 버튼 생성여부 체크
 * @returns {void}
 * @hidden N
 */
scwin.showOptButton = function() {
    // 시장구분이가  유가이면 보여준다.
    if (scwin.gLdMktTp === "1") {
        panel_ReserveTp.show("");
    } else {
        panel_ReserveTp.hide();
    }
};

/**
 * @method
 * @name hiddenCol
 * @description 특정 컬럼 숨기기
 * @returns {void}
 * @hidden N
 */
scwin.hiddenCol = function() {
    if (scwin.gLdMktTp === 1) {
        // 유가일때
        $c.cm.setColumnProp(grd_Grid, "REDISCLS_YN_NM", "Show", false); // 재공시여부 를  hidden

    }
};

/**
 * @method
 * @name setCode
 * @description 기간 from~ to  셋팅
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setCode = async function() {
    //  기간 from~ to  셋팅
    vCurDate = $c.ut.cGetToday("yyyymmdd");
    edt_FromDate.setValue($c.ut.cGetMinusDate2(vCurDate, 7)); // 일주일전 날짜
    edt_ToDate.setValue($c.ut.cGetToday("yyyymmdd")); // 현재날짜

    // 유가 공시팀(26**), 코스닥 공시팀(34**) => 보여준다.
    if (js_dep_cd.substring(0, 2) === '26' || js_dep_cd.substring(0, 2) === '34') {
        panel_2.show("");
    } else {
        panel_2.hide();
    }
    // 팀 리스트 박스(소속부서와 같은 상위부서인 팀)
    // dts_dep.DataID = "/CodeAction.do?method=listDepCdCode&For=R";
    const sbmOptions = {
        id : "sbm_dts_dep",
        action : "/CodeAction.do",
        ref : "",
        target : "dts_dep=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    // 담당자 리스트 박스(소속부서와 같은 상위부서인 팀원)
    const sbmOptions2 = {
        id : "sbm_dts_emp",
        action : "/CodeAction.do",
        ref : "",
        target : "dts_emp=body.content",
        isProcessMsg : false
    };

    const sbmRtn2 = await $c.sbm.executeDynamic(sbmOptions2);
    // TODO Stage2: sbmRtn2 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    // 공시유보유형 리스트  셋팅
    const sbmOptions3 = {
        id : "sbm_dts_ReservTp",
        action : "/CodeAction.do",
        ref : "",
        target : "dts_ReservTp=body.content",
        isProcessMsg : false
    };

    const sbmRtn3 = await $c.sbm.executeDynamic(sbmOptions3);
    // TODO Stage2: sbmRtn3 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name initSearch
 * @description 화면 로딩시 디폴트 검색
 * @returns {void}
 * @hidden N
 */
scwin.initSearch = function() {
    // fn_Search();

    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    //
    // ********************************************************************

};X < !공시유보현황--;
클릭-- > async function() {
    // 일자 체크
    if (edt_FromDate.getValue().length < 8) {
        await $c.win.alert("일자 올바르게 입력하십시오.");
        edt_FromDate.focus();
        return;
    }

    // 일자 체크
    if (edt_ToDate.getValue().length < 8) {
        await $c.win.alert("일자 올바르게 입력하십시오.");
        edt_ToDate.focus();
        return;
    }

    //

    // 유가 공시팀(26**), 코스닥 공시팀(34**) =>  선택부서로
    if (js_dep_cd.substring(0, 2) === '26' || js_dep_cd.substring(0, 2) === '34') {
        scwin.gDepCd = cmb_TeamList.getValue();
        scwin.gEmpNo = cmb_EmpList.getValue();
    } else {
        scwin.gDepCd = ""; // 부서코드 없음 => 전체
        scwin.gEmpNo = "";
    }
    fn_Search();
} < !공시유보현황--;
클릭-- > async function() {
    /******************************************************************
    2009.09.01 채권공시관련 - 채권상장팀이면 시장구분 : 4
     ******************************************************************/
    if (js_bond_yn === "Y") {
        scwin.gLdMktTp = "4";
    }

    /* 2009.09.01 채권공시하면서 수정함. ****************************************************
        상장폐지법인 제외 콤보가 0, 1을 자바로 넘기는데 자바에서는 Y,N 을 체크해서 수정함.
     ***************************************************************************************/
    let listStatCdTemp;
    if (scwin.getChkValue(chb_ListStatCd) === "0") {
        listStatCdTemp = "N";
    } else {
        listStatCdTemp = "Y";
    }
    /**************************************************************************************/

    const sbmOptions = {
        id : "sbm_dts_ReserveList",
        action : "/DisclosureStatus.do",
        ref : "",
        target : "dts_ReserveList=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name setContnId
 * @description 그리드에서 클릭 row의 변수셋팅
 * @param {Object} obj 컴포넌트
 * @returns {void}
 * @hidden N
 */
scwin.setContnId = function(obj) {
    scwin.gAcptNo = dts_ReserveList.getCellData(Number(obj), "ACPT_NO");
    scwin.gMainFormCd = dts_ReserveList.getCellData(Number(obj), "FORM_CD");
    scwin.gFormVer = dts_ReserveList.getCellData(Number(obj), "FORM_VER");
    scwin.gIsurCd = dts_ReserveList.getCellData(Number(obj), "ISUR_CD");
    scwin.gProcDepCd = dts_ReserveList.getCellData(Number(obj), "DEP_CD");

    // alert("부모창:"+gAcptNo+","+gMainFormCd+","+ gFormVer+","+ gIsurCd);

};

/**
 * @method
 * @name getChkValue
 * @description get Chk Value 처리
 * @param {Object} obj 컴포넌트
 * @returns {void}
 * @hidden N
 */
scwin.getChkValue = function(obj) {
    // return (obj.checked) ? "Y" : "N";
    if (obj.checked === true) {
        return obj.getValue();
    } else {
        return "0";
    }
};

/**
 * @method
 * @name setChkValue
 * @description set Chk Value 처리
 * @param {Object} obj 컴포넌트
 * @param {*} booleanVal booleanVal
 * @returns {void}
 * @hidden N
 */
scwin.setChkValue = function(obj, booleanVal) {
    // return (obj.checked) ? "Y" : "N";
    obj.setValue(booleanVal);
};

/**
 * @method
 * @name dts_ReserveList_OnLoadError
 * @description dts_ReserveList 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_ReserveList_OnLoadError = async function() {
    await $c.win.alert(dts_ReserveList);
};

/**
 * @method
 * @name dts_ReserveList_OnLoadCompleted
 * @description dts_ReserveList 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_ReserveList_OnLoadCompleted = async function(rowcount) {
    if (dts_ReserveList.errorMsg) {
        await $c.win.alert(dts_ReserveList.errorMsg);
    } else {
        $c.stf.fillGridHeaderTotalCnt(rowcount, panel_page);
    }
};

/**
 * @method
 * @name btn_Excel_onclick
 * @description 「엑셀저장」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Excel_onclick = function() {
    $c.stf.doLogSave('ULDSTF10400.xml', SCREN_PROCS_TP_CD_07);
    $c.data.downloadGridViewExcel(grd_Grid, {fileName: "공시유보현황 목록", type: "2"});
};

/**
 * @method
 * @name dts_dep_OnLoadCompleted
 * @description dts_dep 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_dep_OnLoadCompleted = function(rowcount) {
    cmb_TeamList.setValue(js_dep_cd);
};

/**
 * @method
 * @name dts_emp_OnLoadCompleted
 * @description dts_emp 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_emp_OnLoadCompleted = function(rowcount) {
    // setObjectValue(cmb_EmpList, js_emp_no) ;

};

/**
 * @method
 * @name cmb_TeamList_onselchange
 * @description cmb_TeamList onselchange 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.cmb_TeamList_onselchange = function() {
    scwin.gDepCd = $c.cp.valueOfIndex(cmb_TeamList, "VALUE", cmb_TeamList.getSelectedIndex());
    if (scwin.gDepCd === '') {
        cmb_EmpList.setValue('');
    }
    dts_emp.UseFilter = true;
    dts_emp.Filter();
    dts_emp.sort("DEP_CD", 0);
    // dts_emp.sort(); // W-Craft 주석처리

};

/**
 * @method
 * @name dts_emp_OnFilter
 * @description 부서코드에  해당하는 사원을 가져온다.
 * @param {Number} row 행 인덱스
 * @returns {void}
 * @hidden N
 */
scwin.dts_emp_OnFilter = function(row) {
    //  부서코드에  해당하는 사원을 가져온다.
    if (scwin.gDepCd === "") {
        // 전체일 경우 모두 보여준다.
        return true;
    } else {
        if (dts_emp.getCellData(row, "dep_cd") === scwin.gDepCd ||
            dts_emp.getCellData(row, "dep_cd") === "") {
            return true;
        } else {
            return false;
        }
    }
};

/**
 * @method
 * @name grd_Grid_OnDblClick
 * @description 클릭된 값 변수에 셋팅
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_Grid_OnDblClick = async function(row, colid) {
    // 클릭된 값 변수에 셋팅
    scwin.setContnId(row);
    if (colid === "DOC_TITLE") {
        await $c.stf.openDisclViewer(scwin.gAcptNo, "R");
    } else if (colid === "RESERV_RSN_NM") {
        // 로그인유저와 공시문서의 부서가 같으면 수정가능    & 당번일때
        if (scwin.gProcDepCd === js_dep_cd ||
            js_duty === 'Y' || js_duty_chrg === 'Y') {
            // 유보사유 및 유보유형 수정화면
            let url = "/dsclproc/ULDSTF10402.gfm";
            let winTitle = "유보처리현황";
            // frame.CreateDialogFrame("reserveMod", url , winTitle ,100, 100, 900, 490+30, "window" );
            await $c.frame.CreateFrame("reserveStat", url, winTitle, 100, 100, 900, 490 + 30, "window", 0, 0, true);
        } else {
            // 유보사유 및 유보유형
            let url = "/dsclproc/ULDSTF10401.gfm";
            let winTitle = "유보처리현황";
            await $c.frame.CreateDialogFrame("reserveStat", url, winTitle, 100, 100, 900, 460 + 30, "window");
        }
    } else if (colid === "ACPT_DDTM") {
        $c.stf.openDisclAllList();
    } else if (colid === "COM_ABBRV") {
        $c.stf.fn_PopupCorpInfo();
    }
};

/**
 * @method
 * @name btn_Search_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Search_onclick = function() {
    fn_CheckCond();
};

/**
 * @method
 * @name img_ToCal_onclick
 * @description img_ToCal 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_ToCal_onclick = function() {
    popUpCalendar2(edt_ToDate);
};

/**
 * @method
 * @name img_FromCal_onclick
 * @description img_FromCal 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_FromCal_onclick = function() {
    popUpCalendar2(edt_FromDate);
};

/**
 * @method
 * @name cmb_PeriodTp_onselchange
 * @description cmb_PeriodTp onselchange 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.cmb_PeriodTp_onselchange = function() {
    const vTp = $c.cp.valueOfIndex(cmb_PeriodTp, "VALUE", cmb_PeriodTp.getSelectedIndex());
    $c.stf.setFromToDate(vTp, edt_FromDate, edt_ToDate);
};

/**
 * @method
 * @name MxDataSet_com_isur_OnFilter
 * @description Mx Data Set com isur On Filter 처리
 * @param {Number} row 행 인덱스
 * @returns {void}
 * @hidden N
 */
scwin.MxDataSet_com_isur_OnFilter = function(row) {
    if (skw !== "" && foColum === "1") {
        f1 = MxDataSet_com_isur.getCellData(row, "COM_ABBRV");
        f2 = MxDataSet_com_isur.getCellData(row, "OLD_COM_ABBRV");
        if (f1.indexOf(skw) !== -1 || f2.indexOf(skw) !== -1) return true;

        else return false;
    } else {
        return true;
    }
};

/**
 * @method
 * @name txb_isur_cd_onblur
 * @description txb_isur_cd 포커스 이탈 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_isur_cd_onblur = function() {
    if (stFocusGrid === false) {
        Grd_com_isur.style.display = "none";
    }
    if (txb_isur_cd.getValue() === "") {
        txb_com_abbrv.setValue("");
    }
};

/**
 * @method
 * @name txb_isur_cd_onfocus
 * @description txb_isur_cd 포커스 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_isur_cd_onfocus = function() {
    Grd_com_isur.style.display = "none";
};

/**
 * @method
 * @name txb_isur_cd_onkeyup
 * @description txb_isur_cd 키 입력 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_isur_cd_onkeyup = function() {
    if (txb_isur_cd.getValue() === "") {
        Grd_com_isur.style.display = "none";
    } else {
        if (window.event.keyCode === 40) {
            // 아래화살표눌렀을때 그리드로 포커스
            Grd_com_isur.focus();
        } else {
            $c.cm.fn_com_isur_nm(window.event.keyCode);
        }
    }
};

/**
 * @method
 * @name Grd_com_isur_OnKeyPress
 * @description Grd com isur On Key Press 처리
 * @param {*} kcode kcode
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnKeyPress = function(kcode) {
    if (kcode === '13') {
        $c.cm.fn_com_Confirm_set();
    }
};

/**
 * @method
 * @name Grd_com_isur_OnDblClick
 * @description Grd_com_isur 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnDblClick = function(row, colid) {
    $c.cm.fn_com_Confirm_set();
};

/**
 * @method
 * @name Grd_com_isur_OnClick
 * @description Grd_com_isur 클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnClick = function(row, colid) {
    Grd_com_isur.style.display = "";
};

/**
 * @method
 * @name Grd_com_isur_OnSetFocus
 * @description Grd com isur On Set Focus 처리
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnSetFocus = function() {
    stFocusGrid = true;
};

/**
 * @method
 * @name Grd_com_isur_OnKillFocus
 * @description Grd_com_isur 포커스 이탈 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnKillFocus = function() {
    stFocusGrid = false;
    Grd_com_isur.style.display = "none";
};

/**
 * @method
 * @name img_com_srch_onclick
 * @description img_com_srch 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_com_srch_onclick = function() {
    /******************************************************************
    	2009.09.01 채권공시관련 - 채권상장팀이면 채권종목만...
     ******************************************************************/
    if (js_bond_yn === "Y") {
        $c.cm.IsurcdSearchBond(txb_isur_cd, txb_com_abbrv);
    } else {
        $c.cm.IsurcdSearch(txb_isur_cd, txb_com_abbrv);
    }
};

/**
 * @method
 * @name gform_onload
 * @description 패널라운드 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.gform_onload = async function() {
    // 패널라운드 처리
    $c.libRoundPanel.PanelToGroupBox(panel_1);
    $c.cm.fn_com_isur(txb_isur_cd, txb_com_abbrv);
    await scwin.setCode();
    scwin.showOptButton();
    scwin.hiddenCol();
    $c.stf.comboCbDataSetPeriod(cmb_PeriodTp);
    scwin.initSearch();
};
